import React, { useContext, useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import './Research.css';
import plotuneLogo from '../assets/logo.png';

const RssIcon = () => <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="18" r="2" /><path d="M4 10a10 10 0 0 1 10 10M4 4a16 16 0 0 1 16 16" /></svg>;

const ResearchLayout = ({ children }) => {
  const [open, setOpen] = useState(false);
  const [rssOpen, setRssOpen] = useState(false);
  const [copyState, setCopyState] = useState('idle'); // idle | copied | failed
  const location = useLocation();
  // This layout replaces the site Header on /research, so it must read the session itself.
  // While the token is being validated (isLoading) render neither state, so a signed-in
  // user never sees a flash of "Log in / Register".
  const { user, isLoading, logout } = useContext(AuthContext) || {};
  const nav =[['/research', 'Overview'], ['/research/reports', 'Reports'], ['/research/methodology', 'Methodology']];
  const rssUrl = `${window.location.origin}/research/rss.xml`;
  // Doherty/Occam: Escape and outside clicks close the RSS popover instead of
  // requiring a precise second click on the small RSS button.
  useEffect(() => {
    if (!rssOpen) return undefined;
    const onKeyDown = (event) => {
      if (event.key === 'Escape') setRssOpen(false);
    };
    const onMouseDown = (event) => {
      if (event.target instanceof Element && !event.target.closest('.rss-control')) {
        setRssOpen(false);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('mousedown', onMouseDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.removeEventListener('mousedown', onMouseDown);
    };
  }, [rssOpen]);
  const copyFeed = async () => {
    if (!navigator.clipboard) { setCopyState('failed'); return; }
    try {
      await navigator.clipboard.writeText(rssUrl);
      setCopyState('copied');
      // Only the success state self-reverts; a clipboard failure must stay truthful
      // until the condition changes, not flip back to "Copy feed link" after 2.4s.
      window.setTimeout(() => setCopyState((current) => (current === 'copied' ? 'idle' : current)), 2400);
    } catch {
      setCopyState('failed');
    }
  };
  return <div className="research-site"><header className="research-header"><div className="research-brand"><a className="research-brand-plotune" href="/" aria-label="Plotune home"><img src={plotuneLogo} alt="" /><span translate="no">Plotune</span></a><Link to="/research" aria-label="Plotune Research home"><strong translate="no">Research</strong></Link></div><button className="research-menu" onClick={() => setOpen(!open)} aria-expanded={open}>Menu</button><nav className={open ? 'is-open' : ''}>{nav.map(([to, label]) => <Link key={to} to={to} className={location.pathname === to ? 'active' : ''} onClick={() => setOpen(false)}>{label}</Link>)}<div className="rss-control"><button className="rss-button" onClick={() => setRssOpen(!rssOpen)} aria-label="RSS options" aria-expanded={rssOpen}><RssIcon /></button>{rssOpen && <div className="rss-popover"><strong>Follow this research</strong><a href={`https://feedly.com/i/subscription/feed/${encodeURIComponent(rssUrl)}`} target="_blank" rel="noreferrer">Open in Feedly</a><button onClick={copyFeed}>{copyState === 'copied' ? 'Feed link copied' : copyState === 'failed' ? 'Copy unavailable: select the link below' : 'Copy feed link'}</button>{copyState === 'failed' && <input readOnly value={rssUrl} onFocus={(e) => e.target.select()} aria-label="RSS feed link" />}</div>}</div>{isLoading ? null : user ? <><Link className="research-login" to="/dashboard" onClick={() => setOpen(false)}>Dashboard</Link><button type="button" className="research-logout" onClick={() => { setOpen(false); logout(); }}>Log out</button></> : <><Link className="research-login" to="/login" onClick={() => setOpen(false)}>Log in</Link><Link className="research-register" to="/register" onClick={() => setOpen(false)}>Register</Link></>}</nav></header><main>{children}</main><footer className="research-footer"><span>(c) {new Date().getFullYear()} <span translate="no">Plotune</span> <span translate="no">Research</span></span><a href="/research/rss.xml">RSS feed</a></footer></div>;
};

export default ResearchLayout;
